    vector<int> minSlidingWindow(vector<int>& nums, int k) {
        deque<int> q;                                   // 存下标，对应的值从队头到队尾递增
        vector<int> res;
        for (int i = 0; i < (int)nums.size(); i++) {
            while (!q.empty() && nums[q.back()] >= nums[i]) {   // 比 nums[i] 大的以后不可能是最小值了
                q.pop_back();
            }
            q.push_back(i);
            if (q.front() <= i - k) {                   // 队头滑出了窗口
                q.pop_front();
            }
            if (i >= k - 1) {                           // 窗口满了：队头就是最小值
                res.push_back(nums[q.front()]);
            }
        }
        return res;
    }
};

