build(a, snap) {
        const A = a.nums, k = a.k, q = [], res = [];
        let cur = -1, prevMin = null;
        const view = (opts = {}) => [
          {
            t: "array",
            label: "nums",
            items: A.map((v, i) => ({
              v,
              cls: i === cur ? "a" : i === opts.expired ? "d" : q.length && i === q[0] && cur >= k - 1 ? "c" : q.includes(i) ? "g" : cur >= 0 && i > cur - k && i <= cur ? "e" : "",
            })),
            ptrs: { ...(cur >= 0 ? { i: cur } : {}), ...(q.length ? { 队头: q[0] } : {}) },
            feeds: opts.feeds || [],
          },
          {
            t: "chips",
            label: "队列（左边是队头，写的是 下标:值）",
            items: q.map((i, idx) => ({ v: `${i}:${A[i]}`, cls: idx === 0 && cur >= k - 1 ? "c" : opts.hlTail && idx === q.length - 1 ? "a" : "g" })),
            empty: "空",
          },
          {
            t: "chips",
            label: "res",
            items: res.map((v, idx) => ({ v, cls: opts.newestRes && idx === res.length - 1 ? "c" : "" })),
            empty: "空",
          },
        ];
        snap("开始", `队列是空的，窗口长度 k = ${k}。`, view(), {
          at: "init",
          facts: [["窗口长度 k", k], ["队列大小", 0], ["队头最小值", "—"], ["res 长度", 0]],
        });
        A.forEach((x, i) => {
          cur = i;
          const popped = [];
          const beforePopLen = q.length;
          while (q.length && A[q[q.length - 1]] >= x) popped.push(q.pop());
          if (popped.length) {
            snap(
              "队尾淘汰",
              `新来 nums[${i}] = ${x}。队尾 ${popped.map((j) => `${j}:${A[j]}`).join("、")} 都 &gt;= ${x}，它们比 ${x} 先离开窗口又更大，不可能再是最小值，弹掉。`,
              view({
                feeds: popped.map((j, idx) => ({
                  from: i,
                  to: j,
                  win: idx === 0,
                  ...(idx === 0 ? { label: `淘汰≥${x}` } : {}),
                })),
              }),
              {
                at: ["loop", "pop"],
                facts: [
                  ["当前下标 i", `${i} (值 ${x})`],
                  ["淘汰数量", popped.length],
                  ["队列大小", q.length, beforePopLen],
                ],
              },
            );
          }
          const beforePushLen = q.length;
          q.push(i);
          snap(
            "入队",
            `${popped.length ? "" : `新来 nums[${i}] = ${x}，队尾比它小（或队列空）。`}把下标 ${i} 放到队尾，队列保持递增。`,
            view({ hlTail: true }),
            {
              at: popped.length ? "push" : ["loop", "pop", "push"],
              facts: [
                ["当前下标 i", `${i} (值 ${x})`],
                ["队列大小", q.length, beforePushLen],
                ["队头", `${q[0]}:${A[q[0]]}`],
              ],
            },
          );
          if (q[0] <= i - k) {
            const oldLen = q.length;
            const e = q.shift();
            snap(
              "队头过期",
              `队头下标 ${e}（值 ${A[e]}）已经滑出窗口 [${i - k + 1}, ${i}]，从队头弹掉。`,
              view({ expired: e }),
              {
                at: "expire",
                facts: [
                  ["当前窗口", `[${i - k + 1}, ${i}]`],
                  ["队列大小", q.length, oldLen],
                  ["队头", `${q[0]}:${A[q[0]]}`, `${e}:${A[e]}`],
                ],
              },
            );
          }
          if (i >= k - 1) {
            const oldResLen = res.length;
            const curMin = A[q[0]];
            res.push(curMin);
            snap(
              "记下最小值",
              `窗口 [${i - k + 1}, ${i}] 满了，队头 ${q[0]}:${curMin} 就是当前窗口最小值。`,
              view({
                newestRes: true,
                feeds: q[0] !== i ? [{ from: q[0], to: i, win: true, label: `min=${curMin}` }] : [],
              }),
              {
                at: "record",
                kind: "ok",
                facts: [
                  ["当前窗口", `[${i - k + 1}, ${i}]`],
                  ["窗口最小值", curMin, prevMin ?? undefined],
                  ["res 长度", res.length, oldResLen],
                ],
              },
            );
            prevMin = curMin;
          }
        });
        cur = -1;
        snap("完成", `结果是 [${res.join(", ")}]。`, view(), {
          at: "done",
          kind: "ok",
          ans: res.slice(),
          facts: [["窗口长度 k", k], ["res", `[${res.join(", ")}]`]],
        });
      }

demo.random:
() => { const R = (function makeR() {
  const int = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
  const pick = (xs) => xs[int(0, xs.length - 1)];
  const chance = (p) => Math.random() < p;
  const shuffle = (xs) => {
    const a = xs.slice();
    for (let i = a.length - 1; i > 0; i--) {
      const j = int(0, i);
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  };
  const arr = (n, a, b) => Array.from({ length: n }, () => int(a, b));
  const distinct = (n, a, b) => shuffle(Array.from({ length: b - a + 1 }, (_, i) => a + i)).slice(0, n);
  const sorted = (xs) => xs.slice().sort((x, y) => x - y);
  const word = (n, abc) => Array.from({ length: n }, () => pick(abc)).join("");
  const fmt = (x) => JSON.stringify(x);
  const py = (x) => JSON.stringify(x).replace(/null/g, "None").replace(/true/g, "True").replace(/false/g, "False");
  // 二叉树用「堆下标」表示：下标 i 的孩子是 2i+1、2i+2，最多 4 层（下标 < 31）
  const toLc = (heap) => {
    const out = [];
    const q = heap.length && heap[0] != null ? [0] : [];
    while (q.length) {
      const i = q.shift();
      if (i < 0) { out.push(null); continue; }
      out.push(heap[i]);
      for (const c of [2 * i + 1, 2 * i + 2]) q.push(heap[c] != null ? c : -1);
    }
    while (out.length && out[out.length - 1] === null) out.pop();
    return out;
  };
  const trim = (heap) => {
    while (heap.length && heap[heap.length - 1] == null) heap.pop();
    return heap;
  };
  /** 随机形状的树，n 个节点，值由 val(k) 给出 */
  const tree = (n, val, maxId = 30) => {
    const ids = [0];
    let guard = 0;
    while (ids.length < n && guard++ < 500) {
      const p = pick(ids), c = 2 * p + int(1, 2);
      if (c <= maxId && !ids.includes(c)) ids.push(c);
    }
    const heap = [];
    ids.sort((a, b) => a - b).forEach((id, k) => (heap[id] = val(k)));
    for (let i = 0; i < heap.length; i++) if (heap[i] === undefined) heap[i] = null;
    trim(heap);
    return { heap, lc: toLc(heap) };
  };
  /** 把一串不同的值依次插入二叉搜索树，超过 4 层的值丢掉 */
  const bst = (vals) => {
    const heap = [];
    for (const v of vals) {
      let i = 0;
      while (heap[i] != null && i <= 30) i = v < heap[i] ? 2 * i + 1 : 2 * i + 2;
      if (i <= 30) heap[i] = v;
    }
    for (let i = 0; i < heap.length; i++) if (heap[i] === undefined) heap[i] = null;
    trim(heap);
    return { heap, lc: toLc(heap) };
  };
  return { int, pick, chance, shuffle, arr, distinct, sorted, word, fmt, py, tree, bst, toLc };
})(); const r = ((R) => { const nums = R.arr(R.int(4, 9), 1, 12), k = R.int(1, Math.min(4, nums.length)); return { args: { nums, k }, note: `nums = ${R.fmt(nums)}, k = ${k}` }; })(R); return { args: r.args, note: r.note }; }
